package com.foodydelivery.tracker.order; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class OrderService {private final OrderRepository repo; public OrderService(OrderRepository r){repo=r;} @Transactional public OrderDtos.Response create(OrderDtos.CreateRequest r,String email){Order o=new Order();o.setCustomer(r.customer().trim());o.setItems(r.items().trim());o.setDeliveryAddress(r.deliveryAddress().trim());o.setOwnerEmail(email);return OrderDtos.Response.of(repo.save(o));} public List<OrderDtos.Response> list(String e){return repo.findAllByOwnerEmailOrderByCreatedAtDesc(e).stream().map(OrderDtos.Response::of).toList();} public OrderDtos.Response get(Long id,String e){return OrderDtos.Response.of(repo.findByIdAndOwnerEmail(id,e).orElseThrow(()->new NoSuchElementException("Pedido não encontrado")));} @Transactional public OrderDtos.Response updateStatus(Long id,OrderDtos.StatusRequest r,String e){Order o=repo.findByIdAndOwnerEmail(id,e).orElseThrow(()->new NoSuchElementException("Pedido não encontrado"));o.setStatus(r.status());return OrderDtos.Response.of(o);}}
